#!/usr/bin/env bash
set -Eeuo pipefail
trap 'status=$?; echo "v0.53 parent receipt preparation failed at line ${LINENO}: ${BASH_COMMAND}" >&2; exit "$status"' ERR

if [ "$#" -ne 2 ]; then echo "usage: prepare-v0530-parent-receipt.sh ARTIFACT_ROOT REPOSITORY_ROOT" >&2; exit 64; fi
artifact_root=$(realpath "$1")
repository=$(realpath "$2")
contract="$repository/contracts/release-locks-v1.json"
receipt="$artifact_root/v0530-parent-lock-receipt.json"
temp_root="${RUNNER_TEMP:-$artifact_root/.v0530-parent-temp}"
mkdir -p "$artifact_root" "$temp_root" "$artifact_root/releases"
command -v gh >/dev/null; command -v jq >/dev/null; command -v sha256sum >/dev/null; command -v unzip >/dev/null; command -v base64 >/dev/null; command -v wc >/dev/null; test -n "${GH_TOKEN:-}"

repo="kimjooyoon/gooo-self-improvement-ledger"
parent_tag="v0.52.0"; parent_release_id=380923246; parent_tag_object="b952230430c3cffb16f3b3cc2f9d33e388c87a4d"; parent_target="a58356a8d3fd40ba8b9d06c41e735df7b62d426b"
parent_asset_id=540435763; parent_asset_name="gooo-self-improvement-ledger-a58356a8d3fd40ba8b9d06c41e735df7b62d426b"; parent_asset_size=57996564; parent_asset_digest="sha256:5560540aaa9d8336b98380ed72e8daed843ab8fcbe27de494c7c726560123686"
parent_manifest_sha="2c6877c2fea2090fe19ab0782872c076dd79507c"; parent_manifest_size=314813; parent_manifest_digest="sha256:8802e3874758fb4f00a2c8ad906f23b51524bdbcc06f308fcf91688a296e7bb9"; parent_lock_set_digest="sha256:31f9885ee4282a1b72308021814c968221003d9bcbdc5b1ec4c7533c2fd59635"

current_count=$(jq '.releases|length' "$contract")
current_lock_set_digest="sha256:$(jq -cS 'del(.releases.evaluator_integrity_projector_durable_release,.releases.semantic_impact_slicer_durable_release,.releases.self_improvement_cycle_detector_durable_release,.releases.closed_loop_self_improvement_usecase_durable_release) | .releases' "$contract" | sha256sum | awk '{print $1}')"
current_manifest_digest="sha256:$(sha256sum "$contract" | awk '{print $1}')"
metadata_state=UNKNOWN; tag_state=UNKNOWN; target_state=UNKNOWN; contents_state=UNKNOWN; public_tag_state=UNKNOWN; asset_bytes_state=UNKNOWN; primary_state=UNKNOWN; reason="PARENT_RELEASE_OR_MANIFEST_NOT_OBSERVED"; unknown_class="PARENT_RECEIPT_UNAVAILABLE"; api_requests=0; metadata_requests=0; asset_requests=0; downloaded_bytes=0
metadata_api() { metadata_requests=$((metadata_requests+1)); api_requests=$((api_requests+1)); gh api "$@"; }
asset_download() { asset_requests=$((asset_requests+1)); api_requests=$((api_requests+1)); gh api -H 'Accept: application/octet-stream' "$@"; }

parent_release='{}'; parent_ref='{}'; parent_tag_record='{}'; parent_contents='{}'; rate_limit='{}'
if parent_release=$(metadata_api "repos/$repo/releases/$parent_release_id" 2>/dev/null); then
  metadata_state=$(jq -r --arg tag "$parent_tag" --arg name "$parent_asset_name" --arg digest "$parent_asset_digest" --argjson id "$parent_release_id" --argjson asset_id "$parent_asset_id" --argjson size "$parent_asset_size" 'if .id==$id and .tag_name==$tag and .draft==false and .prerelease==false and .immutable==true and ([.assets[]? | select(.id==$asset_id and .name==$name and .size==$size and .digest==$digest)]|length)==1 then "CLOSED" else "REFUTED" end' <<<"$parent_release")
else reason="PARENT_V052_RELEASE_METADATA_NOT_OBSERVED"; unknown_class="PARENT_RELEASE_UNAVAILABLE"; fi
if parent_ref=$(metadata_api "repos/$repo/git/ref/tags/$parent_tag" 2>/dev/null); then :; else reason="PARENT_V052_TAG_REF_NOT_OBSERVED"; unknown_class="PARENT_TAG_UNAVAILABLE"; fi
if parent_tag_record=$(metadata_api "repos/$repo/git/tags/$parent_tag_object" 2>/dev/null); then :; else reason="PARENT_V052_TAG_OBJECT_NOT_OBSERVED"; unknown_class="PARENT_TAG_UNAVAILABLE"; fi
if parent_contents=$(metadata_api "repos/$repo/contents/contracts/release-locks-v1.json?ref=$parent_target" 2>/dev/null); then :; else reason="PARENT_V052_LOCK_MANIFEST_NOT_OBSERVED"; unknown_class="PARENT_MANIFEST_UNAVAILABLE"; fi
if rate_limit=$(metadata_api rate_limit 2>/dev/null); then :; else rate_limit='{}'; fi
tag_state=$(jq -r --arg object "$parent_tag_object" 'if .object.sha==$object and .object.type=="tag" then "CLOSED" else "REFUTED" end' <<<"$parent_ref")
target_state=$(jq -r --arg target "$parent_target" 'if .object.sha==$target and .object.type=="commit" then "CLOSED" else "REFUTED" end' <<<"$parent_tag_record")
contents_state=$(jq -r --arg sha "$parent_manifest_sha" --argjson size "$parent_manifest_size" 'if .sha==$sha and .size==$size and .encoding=="base64" then "CLOSED" else "REFUTED" end' <<<"$parent_contents")
if public_refs=$(git ls-remote "https://github.com/$repo.git" "refs/tags/$parent_tag" "refs/tags/$parent_tag^{}" 2>/dev/null); then if test "$(awk -v ref="refs/tags/$parent_tag" '$2==ref {print $1}' <<<"$public_refs")" = "$parent_tag_object" && test "$(awk -v ref="refs/tags/$parent_tag^{}" '$2==ref {print $1}' <<<"$public_refs")" = "$parent_target"; then public_tag_state=CLOSED; else public_tag_state=REFUTED; fi; fi
if [ "$contents_state" = CLOSED ]; then jq -r '.content' <<<"$parent_contents" | tr -d '\r\n' | base64 --decode > "$temp_root/parent-lock-manifest.json"; observed_digest="sha256:$(sha256sum "$temp_root/parent-lock-manifest.json"|awk '{print $1}')"; observed_lock_set="sha256:$(jq -cS '.releases' "$temp_root/parent-lock-manifest.json"|sha256sum|awk '{print $1}')"; if test "$(wc -c <"$temp_root/parent-lock-manifest.json"|tr -d ' ')" != "$parent_manifest_size" || test "$observed_digest" != "$parent_manifest_digest" || test "$observed_lock_set" != "$parent_lock_set_digest"; then contents_state=REFUTED; reason="PARENT_V052_LOCK_MANIFEST_BYTES_CONTRADICTED"; unknown_class="PARENT_RECEIPT_CONTRADICTION"; fi; fi
if [ "$metadata_state" = REFUTED ] || [ "$tag_state" = REFUTED ] || [ "$target_state" = REFUTED ] || [ "$contents_state" = REFUTED ] || [ "$public_tag_state" = REFUTED ]; then primary_state=REFUTED; reason="PARENT_V052_RELEASE_IDENTITY_OR_MANIFEST_CONTRADICTED"; unknown_class="PARENT_RECEIPT_CONTRADICTION"; elif [ "$metadata_state" = CLOSED ] && [ "$tag_state" = CLOSED ] && [ "$target_state" = CLOSED ] && [ "$contents_state" = CLOSED ] && [ "$public_tag_state" = CLOSED ] && [ "$current_count" -eq 70 ] && [ "$current_lock_set_digest" = "$parent_lock_set_digest" ]; then primary_state=CLOSED; reason="IMMUTABLE_V052_PARENT_METADATA_AND_66_LOCK_SET_MATCHED"; else primary_state=UNKNOWN; fi

parent_release_zip="$temp_root/v052-parent-release.zip"; parent_release_root="$temp_root/v052-parent-release"
if [ "$primary_state" != REFUTED ] && asset_download "repos/$repo/releases/assets/$parent_asset_id" > "$parent_release_zip" 2>/dev/null; then
  downloaded_bytes=$(wc -c <"$parent_release_zip"|tr -d ' '); asset_bytes_state=CLOSED
  if test "$downloaded_bytes" != "$parent_asset_size" || test "sha256:$(sha256sum "$parent_release_zip"|awk '{print $1}')" != "$parent_asset_digest"; then asset_bytes_state=REFUTED; primary_state=REFUTED; reason="PARENT_V052_RELEASE_ASSET_BYTES_CONTRADICTED"; unknown_class="PARENT_RECEIPT_CONTRADICTION"; else
    mkdir -p "$parent_release_root"; unzip -q "$parent_release_zip" -d "$parent_release_root"
    test -s "$parent_release_root/report.json"; cp "$parent_release_root/report.json" "$artifact_root/v052-parent-report.json"
    test -s "$parent_release_root/releases/verification.json"; cp -a "$parent_release_root/releases/." "$artifact_root/releases/"; cp "$artifact_root/releases/verification.json" "$artifact_root/releases/v052-parent-verification.json"
    for historical in v0520-parent-lock-receipt.json v0520-live-lock-receipt.json atomic-v0520-wave-v1.json; do if test -s "$parent_release_root/$historical"; then cp "$parent_release_root/$historical" "$artifact_root/$historical"; fi; done
    if test -d "$parent_release_root/v052-products"; then cp -a "$parent_release_root/v052-products" "$artifact_root/v052-products"; fi
  fi
fi
remaining=$(jq -r '.resources.core.remaining // .rate.remaining // null' <<<"$rate_limit"); reset=$(jq -r '.resources.core.reset // .rate.reset // null' <<<"$rate_limit")
jq -S -n --arg schema "gooo/self-improvement-ledger/v0530-parent-lock-receipt/v1" --arg state "$primary_state" --arg reason "$reason" --arg unknown "$unknown_class" --arg repo "$repo" --arg tag "$parent_tag" --argjson release_id "$parent_release_id" --arg tag_object "$parent_tag_object" --arg target "$parent_target" --argjson asset_id "$parent_asset_id" --arg asset_name "$parent_asset_name" --argjson asset_size "$parent_asset_size" --arg asset_digest "$parent_asset_digest" --arg manifest_digest "$parent_manifest_digest" --arg lock_digest "$parent_lock_set_digest" --arg current_lock "$current_lock_set_digest" --arg current_manifest "$current_manifest_digest" --argjson count "$current_count" --argjson requests "$api_requests" --argjson metadata "$metadata_requests" --argjson downloads "$asset_requests" --argjson bytes "$downloaded_bytes" --arg metadata_state "$metadata_state" --arg tag_state "$tag_state" --arg target_state "$target_state" --arg contents_state "$contents_state" --arg public_state "$public_tag_state" --arg asset_state "$asset_bytes_state" --argjson remaining "$remaining" --argjson reset "$reset" '{schema:$schema,parent:{repository:$repo,tag:$tag,release_id:$release_id,tag_object_sha:$tag_object,target_commit_sha:$target,immutable:true,release_asset:{id:$asset_id,name:$asset_name,size_bytes:$asset_size,sha256:$asset_digest},release_lock_manifest:{sha256:$manifest_digest,size_bytes:314813,contents_blob_sha:"2c6877c2fea2090fe19ab0782872c076dd79507c"},parent_lock_set_digest:$lock_digest},primary:{state:$state,reason:$reason,unknown:(if $state=="UNKNOWN" then {stage:"PARENT_RECEIPT",step:"READ_IMMUTABLE_V052_RECEIPT",reason:$reason,unknown_class:$unknown,next_operation:"RUN_FULL_66_LOCK_AUDIT",blocked_by:["v052-parent-release-receipt"]} else null end),refuted:(if $state=="REFUTED" then {stage:"PARENT_RECEIPT",step:"COMPARE_IMMUTABLE_V052_RECEIPT",reason:$reason,unknown_class:$unknown,next_operation:"RUN_FULL_66_LOCK_AUDIT",blocked_by:["v052-parent-release-receipt-contradiction"]} else null end),api_observation:{requests:0,selected:0,executed:0,reused:(if $state=="CLOSED" then 66 else 0 end),bytes_read:0,bytes_downloaded:0,source:(if $state=="CLOSED" then "PARENT_V052_RELEASE_RECEIPT_REUSE" else "PENDING_FULL_66_LOCK_AUDIT" end)}},lock_set:{current_count:$count,current_digest:$current_lock,parent_count:66,parent_digest:$lock_digest,unchanged_66_lock_set:($current_lock==$lock_digest)},release_lock_manifest:{current_digest:$current_manifest,parent_digest:$manifest_digest,parent_contents_blob_sha:"2c6877c2fea2090fe19ab0782872c076dd79507c",parent_contents_size_bytes:314813},parent_input_observation:{api_requests:$requests,metadata_api_requests:$metadata,release_asset_download_requests:$downloads,bytes_downloaded:$bytes,observed_states:{release_metadata:$metadata_state,tag_ref:$tag_state,tag_object:$target_state,contents:$contents_state,public_tag_refs:$public_state,release_asset_bytes:$asset_state},rate_limit:{remaining:$remaining,reset:$reset,observed:($remaining!=null and $reset!=null)},source:"GITHUB_API_AND_IMMUTABLE_RELEASE_ASSET"},full_fallback:{required:($state!="CLOSED"),state:(if $state=="CLOSED" then "NOT_REQUIRED" else "PENDING" end),selected:(if $state=="CLOSED" then 0 else 66 end),executed:0,reused:(if $state=="CLOSED" then 66 else 0 end)},authority:{verification:"GITHUB_ACTIONS",github_token:"github.token",repository_writes:0,local_test_executions:0,cross_project_required_gates:0,caller_owned_temp_outputs_only:true}}' > "$receipt"
echo "v0.53 parent receipt: primary=$primary_state metadata_api_requests=$metadata_requests asset_download_requests=$asset_requests current_locks=$current_count reused_66=$(if test "$primary_state" = CLOSED; then echo 66; else echo 0; fi)"
